-- 2404 🏋️ Exercises from the book "catalan-academy-coaching-u7-12-the-world-s-best-youth-training-program-110-pract" into the exercise catalog (mig 2191).
-- Every practice the book sets out, in OUR OWN WORDS, with app page numbers
-- (the diagram is the book page).  Written by scripts/exercises/sync.py load.
-- Re-runnable: clears this book's exercises first.
BEGIN;
DELETE FROM exercises WHERE book_id = (SELECT id FROM coaching_books WHERE slug = 'catalan-academy-coaching-u7-12-the-world-s-best-youth-training-program-110-pract');
INSERT INTO exercises (title, category_id, opposition, moment, source_id, book_id, page_from, page_to, source_ref, coach,
  objective, setup, procedure, rules, progressions, coaching_points, players_text, min_players, max_players,
  area_text, area_length_m, area_width_m, duration_min, has_goals, has_keepers, directional, age_text, sort_order)
SELECT v.t, c.id, v.opp, v.m, b.source_id, b.id, v.pf::int, v.pt::int, v.ref, v.coach, v.obj, v.setup, v.proc, v.rules, v.prog, v.cp,
  v.players, v.mn::int, v.mx::int, v.area, v.len::real, v.wid::real, v.dur::real, v.goals::boolean, v.gk::boolean, v.dir::boolean, v.age, v.so
FROM (VALUES
  ('Name-calling handball passing warm-up', 'warm_up', 'unopposed', NULL, 14, 14, 'Warm-Up 1', NULL, 'Communication and awareness by naming the receiver before each throw.', '20x20 m square, 10 players in two bib colours spread out, one ball.', 'Players throw and catch the ball to anyone in the square, always calling out the receiver''s name before releasing it and then moving to a new space.', 'Must call the receiver''s name before throwing.', 'After about 5 minutes it becomes the two-team game (Warm-Up 2).', 'Talk early; move into space to offer an option; quick accurate throws to keep tempo.', '10 players', 10, 10, '20 x 20 m', 20.0, 20.0, 5.0, false, false, false, 'U7-U12', 10),
  ('Handball keep-ball team game, name-calling', 'warm_up', 'opposed', NULL, 15, 15, 'Warm-Up 2', NULL, 'Communication, support movement and keeping the ball with the hands as a team.', '20x20 m square, two teams (blue v white), one ball; can go up to 5v5.', 'Teams keep the ball by throwing and catching; ten throws in a row without losing it scores a point. Turnovers or drops give the ball to the other team.', 'Thrower must shout the receiver''s name; 10 consecutive throws = 1 point.', 'Progression of Warm-Up 1; grow to 5v5.', 'Communicate early; move to offer passing angles; quick accurate throws.', '2 teams, up to 5v5', 10, 10, '20 x 20 m', 20.0, 20.0, 5.0, false, false, false, 'U7-U12', 20),
  ('Football tennis in pairs over a line', 'warm_up', 'unopposed', NULL, 16, 16, 'Warm-Up 3', NULL, 'Aerial ball control with both feet and different body parts.', '20x20 m, pairs facing each other across a marked dividing line, no outer boundaries.', 'Partners volley the ball back and forth over the line; it may bounce once on the receiver''s side before being returned.', 'One bounce allowed after the line.', 'Vary the touches (1, 2 or 3 before returning); set sequence 1-2-3 touches then back to 1; partner calls the body part to control with; competition - which pair keeps the rally longest (1 bounce or none).', 'Spread out, use both feet, strike with the instep for control.', 'Pairs', 2, NULL, '20 x 20 m', 20.0, 20.0, 10.0, false, false, false, 'U7-U12', 30),
  ('Juggling in pairs then pass', 'warm_up', 'unopposed', NULL, 17, 17, 'Warm-Up 4', NULL, 'Ball control in the air and accurate passing to a partner.', '20x20 m, players in pairs spread over the area, one ball per pair.', 'Each player keeps the ball up with 2-3 controlled touches then passes it accurately to the partner, who does the same.', '2-3 juggles before each pass.', 'Pairs juggle and pass while moving sideways together.', 'Use all the space, both feet, instep contact.', 'Pairs', 2, NULL, '20 x 20 m', 20.0, 20.0, 8.0, false, false, false, 'U7-U12', 40),
  ('Individual juggling with bounce progressions', 'warm_up', 'unopposed', NULL, 18, 18, 'Warm-Up 5', NULL, 'Coordination and foot control through juggling with a bounce between touches.', '20x20 m, every player has a ball.', 'Players juggle alone, letting the ball bounce once between touches, working through four stages: right foot only, left foot only, alternating feet, then alternating feet with a hand clap on each touch.', NULL, 'Four stages as described.', 'Eyes on the ball, balance, instep, light touches, adjust feet to stay under the ball.', 'Any number, 1 ball each', NULL, NULL, '20 x 20 m', 20.0, 20.0, 5.0, false, false, false, 'U7-U12', 50),
  ('Juggling while walking through cone gates', 'warm_up', 'unopposed', NULL, 19, 19, 'Warm-Up 6', NULL, 'Juggling control combined with movement, actions and awareness.', '20x20 m with about 15 small cone gates scattered at random; one ball each.', 'Players juggle and progress through: alternate feet with a clap then a squat; react to coach commands (arms up, hand on ear, hand on head) while juggling; walk around the cones while juggling.', NULL, 'Three stages as described.', 'Soft close touches, stay balanced when adding actions, lift the head to avoid others.', 'Any number, 1 ball each', NULL, NULL, '20 x 20 m', 20.0, 20.0, 5.0, false, false, false, 'U7-U12', 60),
  ('4-team juggling relay round squares', 'warm_up', 'unopposed', NULL, 20, 20, 'Warm-Up 7', NULL, 'Controlled touches and team coordination in a juggling race.', '30x30 m with 4 squares, a team of 3 in each square.', 'Each team keeps the ball up in its square and every player must touch it before the team moves on to the next square; first team to complete a lap of all four squares wins.', 'All 3 must touch before moving; if the ball hits the ground they retry before moving.', NULL, 'Right surface of the foot, coordinate with teammates, set body shape early.', '4 teams of 3', 12, 12, '30 x 30 m', 30.0, 30.0, 8.0, false, false, false, 'U7-U12', 70),
  ('Bib tag dribbling game', 'warm_up', 'opposed', NULL, 21, 21, 'Warm-Up 8', NULL, 'Running with the ball under pressure while protecting it and attacking opponents.', '20x20 m, two teams, everyone dribbling a ball with a bib tucked in the back of the shorts.', 'While dribbling, players try to pull the bibs off opponents and protect their own; first team to take all the opposing bibs wins.', 'Must keep dribbling own ball.', NULL, 'Speed, keep the ball the right distance, balance, use foot furthest from opponent, both feet, scan.', '2 teams', NULL, NULL, '20 x 20 m', 20.0, 20.0, 5.0, false, false, false, 'U7-U12', 80),
  ('Knockout shielding game with juggling', 'warm_up', 'opposed', NULL, 22, 22, 'Warm-Up 9', NULL, 'Shielding and close control while attacking others'' balls.', '20x20 m square, all players inside with a ball each.', 'Players protect their own ball and try to knock others'' balls out of the square. Knocked-out players go outside and juggle; last player left with a ball wins.', 'Eliminated when your ball leaves the square.', NULL, 'Close control, use the body to shield, scan for threats and chances.', 'Any number, 1 ball each', NULL, NULL, '20 x 20 m', 20.0, 20.0, 5.0, false, false, false, 'U7-U12', 90),
  ('Knockout shielding, eliminated pairs chase', 'warm_up', 'opposed', NULL, 23, 23, 'Warm-Up 10', NULL, 'Shielding and ball protection with growing pressure.', '20x20 m square, all players inside with a ball each.', 'Same knockout game, but knocked-out players join hands with another eliminated player and hunt together to knock out more balls; last player with a ball wins.', 'Eliminated players hold hands in pairs to chase.', NULL, 'Close control, shield with the body, scan.', 'Any number, 1 ball each', NULL, NULL, '20 x 20 m', 20.0, 20.0, 5.0, false, false, false, 'U7-U12', 100),
  ('4-team knockout ball protection', 'warm_up', 'opposed', NULL, 24, 24, 'Warm-Up 11', NULL, 'Protecting the ball and attacking other teams'' balls as a team.', '20x20 m square, 4 teams of 3, each player with a ball.', 'Players shield their own ball and knock other teams'' balls out. Eliminated players juggle outside; the team owning the last player with a ball wins.', 'Eliminated when the ball leaves the square.', NULL, 'Close control, shield with the body, scan.', '4 teams of 3', 12, 12, '20 x 20 m', 20.0, 20.0, 5.0, false, false, false, 'U7-U12', 110),
  ('Juggling pairs into 1v1 gate dribble', 'warm_up', 'opposed', NULL, 25, 25, 'Warm-Up 12', NULL, 'Quick transition from ball control into 1v1 dribbling.', '30x20 m with several small cone gates scattered; pairs (blue v white) juggle together.', 'Pairs juggle and pass keeping the ball up. On the coach''s GO they play 1v1; the player with the ball tries to dribble through any gate for a point and keeps going through other gates until the coach resets.', 'Dribble through a gate = 1 point.', NULL, 'Turn quickly to face the defender, low centre of gravity, feints and changes of direction, shield with body and arm.', 'Pairs, 1v1', 2, NULL, '30 x 20 m', 30.0, 20.0, 10.0, false, false, true, 'U7-U12', 120),
  ('Three 3v1 rondos with colour rotation', 'rondo', 'opposed', NULL, 26, 26, 'Warm-Up 13', NULL, 'Receiving on the back foot and quick rotation between rondos.', 'Three adjacent 10x10 m squares, each a 3v1 with four players of different colours.', 'Each square plays 3v1. When the coach calls a colour, those three players quickly rotate anticlockwise into the next square; play never stops.', 'Receive with the back foot.', NULL, 'Open body shape, receive on the foot furthest from the ball, move early to make a passing line.', '12 players, 3 x 3v1', 12, 12, '10 x 10 m squares', 10.0, 10.0, 10.0, false, false, false, 'U7-U12', 130),
  ('Handball keep-ball into 5v5 football', 'warm_up', 'opposed', NULL, 27, 27, 'Warm-Up 14', NULL, 'Adapting between game types and quick transition into a football possession game.', 'A 10x20 m handball zone next to a 30x20 m football area; two teams of 5.', 'Teams play 5v5 handball; after 5 consecutive throws, 4 players from each side switch into the larger area for 5v5 football possession (with the ball played in).', '5 consecutive passes triggers the switch.', NULL, 'Transition immediately on the 5th pass, spread for width and depth, nearest presses while others block lanes.', '5v5', 10, 10, '40 x 20 m (10x20 + 30x20)', 40.0, 20.0, 10.0, false, false, false, 'U7-U12', 140),
  ('Dribbling with turns and moves on number call', 'technical', 'unopposed', NULL, 31, 31, 'Running with the Ball 1', NULL, 'Execute dribbling turns and skill moves with control and sharpness.', '20x20 m square, every player dribbling a ball.', 'Players dribble freely; the coach shouts a number and each player performs the matching move: 1 scissors, 2 Ronaldo chop, 3 inside-outside touches, 4 drag-over/step-over, 5 Maradona, 6 Cruyff turn.', NULL, 'Confident players add their own advanced skills.', 'Clean, sharp execution; be creative and call out the name of any new skill.', 'Any number, 1 ball each', NULL, NULL, '20 x 20 m', 20.0, 20.0, 5.0, false, false, false, 'U7-U12', 150),
  ('Self-throw aerial control then gate dribble', 'technical', 'unopposed', NULL, 32, 32, 'Running with the Ball 2', NULL, 'First touch on an aerial ball followed by quick dribbling.', '20x20 m with about 15 cone gates scattered; each player has a ball.', 'Players throw the ball up, cushion it with the inside or outside of the foot, then dribble through a gate. They count successful controls and gates in a set time to compete.', 'Count controls plus gates within the time limit.', NULL, 'Cushion to keep it close, both feet, vary the foot surface, accelerate after the touch.', 'Any number, 1 ball each', NULL, NULL, '20 x 20 m', 20.0, 20.0, 10.0, false, false, false, 'U7-U12', 160),
  ('Star-pattern dribbling between five stations', 'technical', 'unopposed', NULL, 33, 33, 'Running with the Ball 3', NULL, 'Running with the ball with close control and head up.', '20x20 m with five stations A-E in a star layout; one player at B-E and two at the start A with balls.', 'Player 1 dribbles from A to B and hands over; the receiver dribbles on to C, then D, E and back to A, tracing a star. Player 6 starts a second ball once the first reaches C.', NULL, NULL, 'Both feet, close control, keep head up to scan.', '6 players', 6, NULL, '20 x 20 m', 20.0, 20.0, 5.0, false, false, false, 'U7-U12', 170),
  ('Star-pattern dribbling with central feint', 'technical', 'unopposed', NULL, 34, 34, 'Running with the Ball 4', NULL, 'Slowing, feinting past cones in the centre and accelerating away.', 'Same 20x20 m star of five stations, plus a ring of cones in the centre.', 'Each runner dribbles into the central cones, slows, fakes as if beating a defender, then accelerates to the next station. Second ball starts once the first reaches station C.', NULL, 'Add a passive defender in the centre.', 'Head up, both feet, slow before the cones then accelerate, if paths cross wait and feint.', '6 players', 6, NULL, '20 x 20 m', 20.0, 20.0, 5.0, false, false, false, 'U7-U12', 180),
  ('Six turns between cones on coach call', 'technical', 'unopposed', NULL, 35, 35, 'Running with the Ball 5', NULL, 'Mastering six standard dribbling turns.', '20x20 m with cones in the corners and a central square; players with a ball each.', 'Players dribble towards a cone, perform the turn the coach calls, then accelerate to the next cone. Turns: outside cut, step-over, double scissors, drag-back, roll-over and turn, Cruyff.', NULL, NULL, 'Keep the ball moving, use both feet for every turn.', 'Any number, 1 ball each', NULL, NULL, '20 x 20 m', 20.0, 20.0, 10.0, false, false, false, 'U7-U12', 190),
  ('Double square feint and change of direction', 'technical', 'unopposed', NULL, 36, 36, 'Running with the Ball 6', NULL, 'Fast changes of direction, explosive acceleration and close control.', '20x20 m outer square with a small inner square of red cones; a player with a ball in each corner.', 'On the coach''s signal players dribble to the nearest inner cone, feint right and burst away left to the next corner station, then keep rotating.', NULL, NULL, 'Keep the ball close approaching the cone, sell the feint with the body, explode after the change of direction.', '4+ players, 1 ball each', 4, NULL, '20 x 20 m', 20.0, 20.0, 10.0, false, false, false, 'U7-U12', 200),
  ('Running with the ball race to catch opponent', 'technical', 'opposed', NULL, 37, 37, 'Running with the Ball 7', NULL, 'Running with the ball at speed in a relay-chase race.', '20x20 m with a cone-gate circuit around the edge; two teams of 3 start in opposite corners.', 'The first player of each team sets off together, dribbling round the circuit through the gates and leaving the ball for the next teammate at the next gate, trying to catch the player in front. The coach can call CHANGE to reverse direction.', 'First team to have all 3 players complete their lap wins.', NULL, 'Both feet, right distance from ball for speed and control, head up.', '2 teams of 3', 6, NULL, '20 x 20 m', 20.0, 20.0, 5.0, false, false, false, 'U7-U12', 210),
  ('Dribble at speed to diagonal gate 1v1', 'one_v_one', 'opposed', NULL, 38, 38, 'Running with the Ball 8', NULL, 'Running with the ball at speed and shielding when the defender catches up.', '20x20 m with a cone gate in each corner; attacker/defender pairs start at each corner.', 'On the signal, two attackers run with the ball trying to dribble through the diagonally opposite gate while their defenders chase and try to stop them.', 'Score by dribbling through the opposite gate.', NULL, 'Speed of execution, ball distance, use the far foot, shield by getting the body between defender and ball, feel with an arm.', 'Pairs 1v1', 4, NULL, '20 x 20 m', 20.0, 20.0, 5.0, false, false, true, 'U7-U12', 220),
  ('Escape your partner on number call', 'technical', 'opposed', NULL, 39, 39, 'Running with the Ball 9', NULL, 'Quick reactions and turns to escape an opponent while keeping the ball.', '20x20 m, pairs numbered 1 and 2, each with a ball.', 'When the coach calls a number, that player must use turns and moves to get away from the partner while keeping control; the player who escapes most often wins.', NULL, NULL, 'React fast, sharp changes of direction, keep the ball close while turning.', 'Pairs', 2, NULL, '20 x 20 m', 20.0, 20.0, 5.0, false, false, false, 'U7-U12', 230),
  ('4v4+2 possession, 3-5 touches each', 'possession', 'overload', 'in_possession', 40, 40, 'Running with the Ball 10', NULL, 'Encourage running with the ball and decision-making in possession.', '20x20 m, two teams of 4 plus 2 jokers who play for the team in possession.', 'Teams keep the ball with the jokers'' help; each player takes 3-5 touches before passing, carrying the ball and choosing the best option. Jokers stay inside and rotate every 5 minutes.', 'Minimum 3-5 touches per player.', NULL, 'High intensity, free fluid movement, use touches to scan and carry away from opponents.', '4v4+2', 10, 10, '20 x 20 m', 20.0, 20.0, 20.0, false, false, false, 'U7-U12', 240),
  ('Receiver v defender among three servers', 'passing_opposed', 'opposed', 'in_possession', 44, 44, 'Passing and Receiving 1', NULL, 'Creating space to receive and returning first time under pressure.', '5x5 m (central area) with 3 servers in a triangle round it, each with a ball; 1 receiver and 1 defender inside.', 'The receiver checks away to lose the defender, receives from a server and plays it back first time for a point, then works to receive from each of the other servers; all three = 3 points.', 'One-touch return; if the defender intercepts, they swap with the receiver.', NULL, 'Be patient for the open pass, clever movement and timing to lose the marker, clean one-touch returns, realistic defending; servers vary distance.', '5 players (1v1+3)', 5, 5, '5 x 5 m', 5.0, 5.0, NULL, false, false, false, 'U7-U12', 250),
  ('Name-call passing, follow pass into next grid', 'passing_unopposed', 'unopposed', 'in_possession', 45, 45, 'Passing and Receiving 2', NULL, 'Scanning and communication while passing and moving between grids.', '20x20 m split into four 10x10 m grids; two teams of 6, three players of each team per grid.', 'Each team passes only among its own players, calling the receiver''s name before passing, then follows the pass into that grid. Both teams share the space but play independently.', 'Call the name before passing; follow your pass.', NULL, 'Call loudly and clearly, scan before receiving and avoid being blocked, move fast into the new grid.', '12 players, 2 teams of 6', 12, 12, '20 x 20 m', 20.0, 20.0, NULL, false, false, false, 'U7-U12', 260),
  ('Pass and move across six grids, 3 balls', 'passing_unopposed', 'unopposed', 'in_possession', 46, 46, 'Passing and Receiving 3', NULL, 'Continuous passing and moving with directional first touch and support.', '30x20 m divided into 6 equal grids, a group of players spread across them with 3 balls in play.', 'Players pass and move continuously with three balls at once, keeping a high tempo, offering quick support for the next receiver and keeping spacing across the area.', NULL, NULL, 'Directional control on the back foot, move straight after passing, scan to anticipate.', 'Group of about 12', NULL, NULL, '30 x 20 m', 30.0, 20.0, NULL, false, false, false, 'U7-U12', 270),
  ('Pairs passing into 1v1 duel on GO', 'one_v_one', 'opposed', NULL, 47, 47, 'Passing and Receiving 4', NULL, 'Purposeful passing then quick transition into a 1v1.', 'Same 30x20 m grids as the previous practice, players in pairs within the grids.', 'Pairs pass freely to each other; on the coach''s GO they immediately play a 1v1 inside their grid. Pairs change partners every minute.', NULL, NULL, 'Use different foot surfaces and pass types, pass with purpose, react quickly, receive with a body shape that protects the ball.', 'Pairs', 2, NULL, '30 x 20 m', 30.0, 20.0, NULL, false, false, false, 'U7-U12', 280),
  ('2v1 end-to-end gauntlet through middle zone', 'one_v_one', 'overload', 'in_possession', 48, 48, 'Passing and Receiving 5', NULL, 'Combining in a 2v1 to pass and dribble past a defender.', '20x10 m (diagram shows a longer area) in three horizontal zones; 2-3 white defenders in the middle zone; blue attacking pairs at both end lines with a ball each.', 'On the coach''s call an attacking pair tries to get through the middle zone past the defenders by passing and dribbling to reach the opposite end. Success = 1 point.', 'If a defender wins it, they swap with the attacker who lost it.', NULL, 'Angled support runs, release the pass at the right moment, feints and disguise; defenders read lanes and press with control.', '2v1 pairs plus 2-3 defenders', NULL, NULL, '20 x 10 m', 20.0, 10.0, NULL, false, false, true, 'U7-U12', 290),
  ('2v1 then 1v1 then 1v1 v GK gauntlet', 'one_v_one', 'overload', 'in_possession', 49, 49, 'Passing and Receiving 6', NULL, 'Breaking lines through successive duels and finishing.', '30x20 m with a goal and GK, split into 4 horizontal zones and in half vertically; 2 teams of 4 switching between attack and defence.', 'Two attackers combine to beat a defender (2v1) in the first zone, then only one goes on into the middle zone to beat a second defender 1v1, and if successful enters the final zone to score 1v1 against the goalkeeper.', NULL, 'Teams switch roles often.', 'Move to open passing lanes, width and quick combinations, positive first touch and change of speed in the 1v1s.', '2 teams of 4 + GK', 9, 9, '30 x 20 m', 30.0, 20.0, NULL, true, true, true, 'U7-U12', 300),
  ('2v2+4 pass or dribble through gates', 'positional_game', 'overload', 'in_possession', 50, 50, 'Passing and Receiving 7', NULL, 'Decision-making between passing and dribbling through gates.', '25x25 m with 10-12 mini cone gates; 4 teams of 2 and 4 jokers (one per side) playing for the team in possession.', 'Two simultaneous 2v2 games; teams score by passing through a gate to a teammate or dribbling through one.', '1 point per gate; the same team cannot use a gate twice in a row.', NULL, 'Scan for open gates, weighted passes, creative movement, use the jokers, decide when to pass or dribble.', '2 x 2v2 (+4 jokers)', 12, 12, '25 x 25 m', 25.0, 25.0, NULL, false, false, true, 'U7-U12', 310),
  ('3v3+2 end-to-end with bonus squares', 'positional_game', 'overload', 'in_possession', 51, 51, 'Passing and Receiving 8', NULL, 'Balancing safe possession with progression to end zones.', '25x15 m with an end zone at each end and two small squares at the sides; 3v3 plus 2 neutral jokers.', 'Coach plays in; the team in possession tries to move the ball from one end zone to the other for 3 points, and earns 1 bonus point for receiving in either square.', 'Jokers cannot score.', NULL, 'Patience - keep it if no safe forward pass, recognise dribble or pass, move off the ball to create space.', '3v3+2', 8, 8, '25 x 15 m', 25.0, 15.0, NULL, false, false, true, 'U7-U12', 320),
  ('5v3 build then 2v1 and finish', 'phase_of_play', 'overload', 'in_possession', 52, 52, 'Passing and Receiving 9', NULL, 'Patient circulation then attacking combinations to finish.', '30x20 m with a goal and GK: large low zone, middle zone with cone gates, final zone.', 'Coach passes in for 5v3 in the low zone; after 5 consecutive passes play can move on. The last two players to touch the ball go 2v1 in the middle zone and must dribble through a cone gate, then the final player finishes 1v1 against the goalkeeper.', '5 passes before progressing; must dribble through a cone gate.', NULL, 'Good circulation and patience, find free space, width and timing in the 2v1, composure and technique against the GK.', '5v3 -> 2v1 -> 1v1 v GK', 9, NULL, '30 x 20 m', 30.0, 20.0, NULL, true, true, true, 'U7-U12', 330),
  ('4v4+2 wide jokers, overload to score', 'small_sided_game', 'overload', 'in_possession', 53, 53, 'Passing and Receiving 10', NULL, 'Using wide jokers to create numerical superiority before shooting.', '30x20 m with two goals and GKs, a halfway line and two side zones where only the jokers play.', 'Coach starts play; a team works the ball into its attacking half with the jokers'' help. Once it has a numerical advantage in the attacking half it may shoot. Both teams have the same aim.', 'Only jokers in the wide zones; can only score with an overload in the attacking half.', NULL, 'Movement off the ball to stretch defenders, scan to judge where space is.', '4v4+2 + GKs', 12, 12, '30 x 20 m', 30.0, 20.0, NULL, true, true, true, 'U7-U12', 340),
  ('3v1 rondo, back-foot receiving', 'rondo', 'overload', 'in_possession', 56, 56, 'Rondo 1', NULL, 'Getting into passing lines and receiving on the back foot.', '5x5 m square, 3 attackers on the edges and 1 defender in a bib inside.', 'The three keep the ball from the defender for as long as possible, moving to create passing options and receiving on the back foot to play on quickly.', 'Defender who wins it hands the bib to the player who lost it and they swap.', NULL, 'Open body to see ball and next pass, receive on the back foot away from pressure, move early to open lines.', '3v1', 4, 4, '5 x 5 m', 5.0, 5.0, 10.0, false, false, false, 'U7-U12', 350),
  ('3v1 rondo, defender dribbles out to escape', 'rondo', 'overload', 'in_possession', 57, 57, 'Rondo 2', NULL, 'Keeping the ball 3v1 and reacting instantly when it is lost.', '5x5 m square, 3 attackers and 1 defender in a bib.', 'The three keep possession; when the defender wins the ball they try to dribble it out of the square as fast as possible while the three try to block the escape. Roles rotate regularly.', 'Defender scores by dribbling out of the area.', NULL, 'Quick passing and sharp movement for angles, keep spacing, stay in the passing line, receive on the back foot, react immediately on losing it.', '3v1', 4, 4, '5 x 5 m', 5.0, 5.0, 15.0, false, false, false, 'U7-U12', 360),
  ('Pass and follow square into 4v1 rondo', 'rondo', 'overload', 'in_possession', 58, 58, 'Rondo 3', NULL, 'Accurate passing with guided control, then quick transition into a rondo.', '10x10 m square, groups of 5 positioned round it.', 'Players pass and follow their pass round the square. On the coach''s call of Rondo, four players immediately enter the area to play 4v1; the last player to have touched the ball before the call becomes the defender.', 'Last player to touch before the call defends.', NULL, 'Correct weight and foot surface, guided control to set up the next action, anticipate the call, make support angles, defend by closing down quickly.', 'Groups of 5', 5, 5, '10 x 10 m', 10.0, 10.0, 15.0, false, false, false, 'U7-U12', 370),
  ('4v2 pairs rondo, split the defenders', 'rondo', 'overload', 'in_possession', 59, 59, 'Rondo 4', NULL, 'Finding and timing passes through the gap between two defenders.', '10x10 m square; two pairs keep the ball, spread on different sides, against a third pair of defenders.', '4v2 rondo where passing between the two defenders scores a point.', 'Split pass = 1 point; if a pair loses the ball, both players swap with the two defenders.', NULL, 'Keep clear lines to support your partner, time movement to exploit gaps, scan, communicate.', '4v2 (3 pairs)', 6, 6, '10 x 10 m', 10.0, 10.0, 15.0, false, false, false, 'U7-U12', 380),
  ('5v2 two-ball rondo, hands and feet', 'rondo', 'overload', 'in_possession', 60, 60, 'Rondo 5', NULL, 'Awareness and communication while keeping two balls at once.', '10x10 m square, 5 attackers v 2 defenders, two balls: one played with feet, one thrown and caught.', 'The five keep both balls at the same time, one by passing and one by throwing; the two defenders try to win either ball.', NULL, NULL, 'Scan to track both balls, communicate clearly, quick accurate passes and throws, good receiving body shape, move into lanes to support.', '5v2', 7, 7, '10 x 10 m', 10.0, 10.0, 10.0, false, false, false, 'U7-U12', 390),
  ('Football tennis court directional rondo', 'rondo', 'opposed', 'in_possession', 61, 61, 'Rondos 6', NULL, 'Finding passing lines and using back-foot directional control to switch the ball between two end boxes past a central interceptor.', 'Two 6x6 m end boxes with 2 players each, split by a 1 m central strip holding one defender; coach with spare balls at the side.', 'Players pass inside their box and switch the ball across to the other box while the central defender tries to cut it out; the ball must never stop.', 'If the ball stops or the defender intercepts, the player who lost it swaps in as defender.', NULL, 'Move into a passing line; receive on the back foot to play forward fast; switch with accurate, well-weighted passes.', '4v1', 5, 5, '13 x 6 m', 13.0, 6.0, 20.0, false, false, true, NULL, 400),
  ('Two side-by-side rondos with recovery swap', 'rondo', 'overload', 'in_possession', 62, 63, 'Rondos 7', NULL, 'Quick accurate passing in a 5v1 rondo plus fast reaction when possession is lost.', 'Two 5x5 m squares 2 m apart, 5 players around each; one square plays 5v1 with a bibbed defender, the other square just keeps the ball (5v0).', 'The 5v1 group tries to string 10 passes for a point. When the defender wins it, the player who lost it takes the bib and runs to press in the other square, which becomes the 5v1.', '10 consecutive passes = 1 point.', NULL, 'Quick accurate passing; open body shape to switch; stay alert to transitions; defenders press hard and cut lanes.', '10 + 1 defender (5v1 and 5v0)', 11, 11, 'Two 5 x 5 m squares (2 m apart)', 5.0, 5.0, 15.0, false, false, false, NULL, 410),
  ('Three 3v1 rondos with rotating defender', 'rondo', 'overload', 'in_possession', 63, 64, 'Rondos 8', NULL, 'Constant decision making and support positioning in tight 3v1 rondos with rotating transitions.', 'Three 3x3 m squares 2 m apart with 3 players around each; two squares play 3v1 (bibbed defender), the third keeps the ball 3v0.', 'Groups aim for 10 passes per point. When a defender wins the ball, the player who lost it takes the bib and runs to defend in the square that had no defender.', '10 consecutive passes = 1 point.', NULL, 'Keep adjusting position to support; high-tempo passing; react quickly on loss; keep width and angles.', '9 + 2 defenders', 11, 11, 'Three 3 x 3 m squares (2 m apart)', 3.0, 3.0, 15.0, false, false, false, NULL, 420),
  ('Three 3v1 rondos with dribble-out transition', 'rondo', 'overload', 'to_attack', 64, 65, 'Rondos 9', NULL, 'Decisive dribbling after winning the ball and intense 3v1 keep-ball.', 'Three 3x3 m squares 2 m apart, 3 players around each; two play 3v1, the third group waits without a ball.', 'When a defender wins the ball he hands the bib to the player who lost it and dribbles into the empty 3v0 square, turning it into a new 3v1.', '10 consecutive passes = 1 point.', 'Possession players can also move to the waiting square after 5 passes.', 'Be decisive when dribbling; stay intense; communicate to organise.', '9 + 2 defenders', 11, 11, 'Three 3 x 3 m squares (2 m apart)', 3.0, 3.0, 15.0, false, false, false, NULL, 430),
  ('Four-zone rondo with changing touch rules', 'rondo', 'overload', 'in_possession', 65, 66, 'Rondos 10', NULL, 'Adapting body shape, support angles and scanning as the passing condition changes zone to zone.', 'Four 10x10 m squares, each with its own condition: unlimited touches, handball, 2 touches, 3 touches. A group of 7 starts 5v2 in the unlimited square, a group of 5 starts 4v1 in the 2-touch square.', 'After 5 passes the player on the ball picks an empty square and the group transitions into it, playing under that square''s condition.', 'Each square has its own touch/handball rule; move after 5 passes.', NULL, 'Set body shape early; correct support angle; scan for the next free square; talk during transitions.', '5v2 and 4v1 (12 players)', 12, 12, '10 x 10 m squares', 10.0, 10.0, 15.0, false, false, false, NULL, 440),
  ('Double rondo: 5v1 with team switch', 'rondo', 'overload', 'in_possession', 66, 67, 'Rondos 11', NULL, 'Competitive keep-ball and fast transition between two connected rondo squares.', 'Two connected 10x10 m squares (blue and yellow); two teams of 5. One team plays 5v1 against one opponent in its square while the rest of the other team waits in the other square.', 'The 5 try for 10 passes. When the defender wins it, he dribbles into the other square to start a 5v1 with his team, and the player who lost the ball becomes the new defender.', '10 consecutive passes = 1 point.', NULL, 'Keep moving to offer options; angles to bypass defender; press aggressively; dribble across quickly and restart.', '2 teams of 5', 10, 10, 'Two 10 x 10 m squares', 20.0, 10.0, 15.0, false, false, false, NULL, 450),
  ('8v2 rondo with central dribble square', 'rondo', 'overload', 'in_possession', 67, 68, 'Rondos 12', NULL, 'Drawing pressure, then breaking the line by dribbling into central space.', '15x15 m area with a 6x6 m central square; 8 players outside, 2 bibbed defenders inside.', 'The 8 keep the ball round the outside; when a gap opens a player dribbles into the central square.', '10 consecutive passes = 1 point; dribbling into the centre square = 1 point. Defender who wins it swaps with the player who lost it.', NULL, 'Good body shape to receive under pressure; draw defenders then play forward; switch to open space; dribble decisively into gaps.', '8v2', 10, 10, '15 x 15 m', 15.0, 15.0, 10.0, false, false, false, NULL, 460),
  ('4v4+2 rondo, find joker in centre', 'rondo', 'overload', 'in_possession', 68, 69, 'Rondos 13', NULL, 'Patient ball circulation to find a joker inside a protected central square.', '20x20 m area with a 6x6 m central square; two teams of 4 plus 2 neutral jokers who play for the team on the ball.', 'Coach serves to one team, which circulates in the big square and tries to pass into a joker in the centre square. Defenders win the ball and play the same with the jokers.', 'Pass to a joker in the central square = 1 point. Defenders may not enter the central square; they press outside it.', NULL, 'Quick circulation; use the jokers; wait for the right moment to play inside; defenders shift together to close lanes.', '4v4+2', 10, 10, '20 x 20 m', 20.0, 20.0, 15.0, false, false, false, NULL, 470),
  ('3v3+3 central space rondo, rotating teams', 'rondo', 'overload', 'in_possession', 69, 70, 'Rondos 14', NULL, 'Patient circulation and timed movement to occupy and exploit central space.', '25x20 m area with a red central square and an end scoring zone at each end; three teams of 3, two in possession (6) against one defending team (3).', 'The two possession teams score by dribbling into or receiving a pass inside the central square. Defenders who win the ball score by dribbling into either end zone. Short rounds, then rotate the defending team.', 'Possession side: ball into central square = 1 point. Defenders: win it and dribble into an end zone = 1 point. Keep score across rotations.', NULL, 'Circulate quickly to shift defenders; be patient for the opening; time runs into the centre; defenders press compactly to block lanes.', '3+3v3', 9, 9, '25 x 20 m', 25.0, 20.0, 15.0, false, false, true, NULL, 480),
  ('Dribble-to-box 4v1 rondos, most balls win', 'rondo', 'overload', 'to_attack', 70, 71, 'Rondos 15', NULL, 'Dribbling control and quick reactions to win and secure possession in competitive rondos.', 'Two 6x6 m squares each with a 3x3 m inner box; two teams of 5 play simultaneous 4v1 rondos; an odd number of balls (e.g. 11) in the middle between squares.', 'On go one player from each team takes a ball to start a 4v1. Possession players score by dribbling into their own team''s inner box and leaving the ball; a defender who wins the ball dribbles it into his team''s box in the other square. The nearest player fetches the next ball.', 'Dribble into your team''s box = 1 point (ball stays). Ends when no balls remain; team with most balls in its box wins.', NULL, 'Be patient before dribbling into the box; react fast to transitions.', '2 teams of 5 (two 4v1)', 10, 10, 'Two 6 x 6 m squares', 6.0, 6.0, 15.0, false, false, true, NULL, 490),
  ('3v3+4 triangle combination rondo', 'rondo', 'overload', 'in_possession', 71, 72, 'Rondos 16', NULL, 'Positional awareness and spreading out to build triangle combinations.', '20x20 m area split into 4 identical triangles; two teams of 3 plus 4 jokers, one on each side, playing with the team on the ball.', 'The team in possession tries to complete 3 straight passes inside one triangle, then moves on to score in other triangles. Defenders who win it keep the ball with the jokers.', '3 consecutive passes inside a triangle = 1 point. Max 2 players from each team inside one triangle; joker passes count.', NULL, 'Scan constantly; circulate to unbalance opponents; spread out but stay close enough to combine; ask where the free space is.', '3v3+4', 10, 10, '20 x 20 m', 20.0, 20.0, 15.0, false, false, false, NULL, 500),
  ('Giant multi-ball rondo with aerial switches', 'rondo', 'overload', 'in_possession', 72, 73, 'Rondos 17', NULL, 'Scanning for space and switching play with accurate lofted passes and control of dropping balls.', 'Large 40x30 m area; 8v2 or 8v3 rondo with 2-3 balls in play at once.', 'Players keep possession of all balls; any switch of play across the area must be made in the air.', 'Every switch of play must be an aerial pass.', '8v3 instead of 8v2.', 'Scan for space and aerial options; correct technique for lofted passes; set body shape early to receive from high; communicate to avoid collisions; quick circulation.', '8v2 (or 8v3)', 10, 11, '40 x 30 m', 40.0, 30.0, 10.0, false, false, false, NULL, 510),
  ('Two-zone pairs rondo with end-to-end switch', 'rondo', 'overload', 'to_defend', 73, 74, 'Rondos 18', NULL, 'Intense defending and fast reactions with constant role switching between two end zones.', '25x10 m area with two 10x10 m end zones and a 5 m middle strip; 5 pairs in different colours. Top zone: two pairs just pass to each other. Bottom zone: two pairs keep the ball against a defending pair (4v2).', 'If the defending pair wins it they keep possession with the remaining pair in that zone, and the pair that lost it sprints to the opposite zone to defend a new 4v2.', 'Pair that loses the ball becomes defenders in the other zone.', NULL, 'Defend with intensity to force mistakes; react fast; back-foot directional control.', '5 pairs (2+2v2 and 2+2)', 10, 10, '25 x 10 m', 25.0, 10.0, 10.0, false, false, false, NULL, 520),
  ('Three-team rondo, break line to switch', 'rondo', 'overload', 'in_possession', 74, 75, 'Rondos 19', NULL, 'Quick passing and back-foot control to complete passes then switch play through a screened middle zone.', '35x15 m area: two 15x15 m end zones and a 5 m middle zone; three teams of 4. Blues start in the bottom zone, whites in the top, yellows in the middle.', 'Two yellows step in to press the blues 4v2; after 5 passes the blues try to switch play past the middle zone to the whites. The 2 yellows left in the middle block lanes; on a successful switch the yellows rotate and a new 4v2 starts on the other side.', '5 passes before switching. If the defenders win the ball, their team swaps roles with the team that lost it.', NULL, 'Quick passing and smart movement for angles; back-foot directional control; scan early for the switch.', '3 teams of 4 (4v2 + 2 screeners)', 12, 12, '35 x 15 m', 35.0, 15.0, 15.0, false, false, true, NULL, 530),
  ('Three-team two-ball rondo with switch', 'rondo', 'overload', 'in_possession', 75, 75, 'Rondos 20', NULL, 'Scanning and coordinated switching of play with two balls in play.', '35x15 m area with two 15x15 m end zones and a 5 m middle zone; three teams of 4. Blues in the bottom zone with 2 balls, whites top, yellows in the middle.', 'One yellow presses the blues (4v1); after 3 passes the blues switch play past the middle zone to the whites. The 3 yellows in the middle try to block and intercept switches.', '3 passes before switching. Defending team that wins a ball swaps roles with the team that lost it.', 'Variation: 3 teams of 5 playing 5v2 rondos.', 'Constant scanning with 2 balls; communicate to time passes and switches; defenders press while middle players screen lanes.', '3 teams of 4 (4v1 + 3 screeners)', 12, 15, '35 x 15 m', 35.0, 15.0, 15.0, false, false, true, NULL, 540),
  ('3v3 with four line jokers', 'possession', 'overload', 'in_possession', 78, 79, 'Possession Games 1', NULL, 'Decision making, support play and using a 7v4 overload to keep the ball.', '30x30 m square; two teams of 3 inside plus 4 jokers, one on each side line, who play for the team on the ball and may only move along their line; coach with balls outside.', 'Team in possession keeps the ball using the jokers to exploit the 7v4 advantage.', 'If the defending team wins the ball, roles switch.', NULL, 'Receive on the back foot to open play; body shape to see options; use jokers for width and depth; play fast in the overload; support at the right angle and distance.', '3v3+4', 10, 10, '30 x 30 m', 30.0, 30.0, 20.0, false, false, false, NULL, 550),
  ('3v3+4 switch into free space', 'possession', 'overload', 'in_possession', 79, 80, 'Possession Games 2', NULL, 'Creating space, switching play into the free area and supporting the receiver quickly.', '40x30 m area; 3v3 in the centre with 4 jokers, one on each side line moving only along it.', 'Team on the ball uses the 7v3 overload to keep it, switches into open space and quickly supports the receiving teammate; on loss they transition to defend.', 'Defenders who win the ball switch roles with the possession team.', NULL, 'Occupy space to open lanes; directional control away from pressure; correct support angle and distance; switch quickly to free space; use jokers to stretch.', '3v3+4', 10, 10, '40 x 30 m', 40.0, 30.0, 20.0, false, false, false, NULL, 560),
  ('4v4+2 create and exploit space', 'possession', 'overload', 'in_possession', 80, 81, 'Possession Games 3', NULL, 'Using movement and positioning to create, find and exploit space and keep the ball as long as possible.', '40x40 m square; two teams of 4 plus 2 roaming jokers inside who play with the team on the ball.', 'Team in possession keeps the ball as long as possible; the coach watches positioning and decisions and stops play to guide when needed.', NULL, NULL, 'Quick accurate ground passes; width and depth to make the pitch big; draw defenders to create space; always give 2 passing options.', '4v4+2', 10, 10, '40 x 40 m', 40.0, 40.0, 10.0, false, false, false, NULL, 570),
  ('Two crossing 2v2+4 games, one space', 'positional_game', 'overload', 'in_possession', 81, 82, 'Possession Games 4', NULL, 'Scanning and awareness in a congested area with two games running through each other.', '20x20 m area; two teams of 4 plus 4 jokers, one per side line, moving only along their line. Two 2v2 games run at once, one playing vertically (players A/B) and one horizontally (C/D), each with its own end jokers.', 'Each 2v2 keeps the ball and tries to pass to an end joker in its direction; defenders win it and attack the same way. Both games share the space, forcing players to watch everything.', 'Pass received by an end joker = 1 point.', NULL, 'Scan constantly to avoid collisions and spot space; precise passes into jokers; good body shape to receive.', '2 x 2v2 (+4 jokers)', 12, 12, '20 x 20 m', 20.0, 20.0, 15.0, false, false, true, NULL, 580),
  ('5v5+2 create space to dribble into', 'possession', 'overload', 'in_possession', 82, 83, 'Possession Games 5', NULL, 'Creating space for a teammate and receiving with a directional touch to dribble into it.', '40x40 m square; two teams of 5 plus 2 roaming jokers who play with the team in possession.', 'Players spread out, keep passing options and drag defenders away so a teammate can receive and dribble into the space created.', '5 consecutive passes = 1 goal.', NULL, 'Quick accurate ground passes; width and depth; draw defenders away; at least 2 options for the ball carrier; directional first touch to dribble into space.', '5v5+2', 12, 12, '40 x 40 m', 40.0, 40.0, 20.0, false, false, false, NULL, 590),
  ('Three-team 4v4+4 continuous movement', 'possession', 'overload', 'in_possession', 83, 84, 'Possession Games 6', NULL, 'Continuous movement, quick decisions and using a numerical advantage to keep the ball.', '40x40 m area; three teams of 4 inside. Two teams (8) start with the ball against the third defending team.', 'The two possession teams combine to string 10 passes. The defenders who win the ball swap roles with the team that lost it, which must transition quickly to defend.', '10 consecutive passes = 1 goal.', NULL, 'Back-foot receiving to play forward and open body to scan; good support angles; directional control away from the opponent; short passes and constant support.', '3 teams of 4 (8v4)', 12, 12, '40 x 40 m', 40.0, 40.0, 20.0, false, false, false, NULL, 600),
  ('Three-team 4v4 with corner supporters', 'possession', 'overload', 'in_possession', 84, 85, 'Possession Games 7', NULL, 'Using fixed corner support players to create angles and keep the ball in an 8v4.', '40x20 m area; three teams of 4. One team keeps the ball inside, helped by a second team stationed one in each of the 4 corners; the third team defends.', 'Possession team plus corner supporters aim for 10 straight passes; if the defenders win it they swap roles with the team that lost it.', '10 consecutive passes = 1 goal; corner players hold their positions.', NULL, 'Move the ball fast to use the 8v4; use corner players to relieve pressure; scan before receiving.', '3 teams of 4 (4+4v4)', 12, 12, '40 x 20 m', 40.0, 20.0, 20.0, false, false, false, NULL, 610),
  ('3v3+8 play short then long', 'possession', 'overload', 'in_possession', 85, 86, 'Possession Games 8', NULL, 'Using short passes to draw the press, then switching with a long pass to exploit space.', '40x40 m square; 3v3 in the centre plus 8 outside jokers around the edge playing for the team on the ball (11v3).', 'Team on the ball plays short combinations with nearby jokers to pull defenders in, then switches long to the far side; the passer then moves to support again.', 'Defenders who win it switch roles.', NULL, 'Good support angles; receive half-turned on the back foot; short passes to draw in; quick accurate long switches; move again after the long pass.', '3v3+8', 14, 14, '40 x 40 m', 40.0, 40.0, 15.0, false, false, false, NULL, 620),
  ('5v5 four-goal multi-directional game', 'small_sided_game', 'opposed', 'in_possession', 86, 86, 'Possession Games 9', NULL, 'Quick circulation, awareness and decision making while attacking any of four goals.', '30x30 m square with a small goal in the middle of each side; two teams of 5.', 'The team in possession completes 3 passes then may score in any goal, keeps the ball after scoring and must attack a different goal next. Defenders who win it switch roles.', '3 consecutive passes before shooting; after a goal keep the ball and attack another goal.', NULL, 'Receive on the back foot; control towards the outside and the goals, not inwards; keep the right distance between ball and foot.', '5v5', 10, 10, '30 x 30 m', 30.0, 30.0, 15.0, true, false, true, NULL, 630),
  ('Mass 1v1 mini duels to two goals', 'one_v_one', 'opposed', 'in_possession', 89, 89, 'Dribbling, Duels and Finishing 1', NULL, 'Positive 1v1 attacking, quick reactions and awareness in a crowded area.', '30x20 m area with a goal at each end; all players paired off in the same space, no bibs; coach with spare balls.', 'Many 1v1 duels run at once in the shared space; each player tries to beat his opponent and score, reacting quickly whenever the ball changes hands. Continuous play with short recovery breaks.', 'No bibs, so players must keep track of their own opponent.', NULL, 'Attack the defender at speed; feints and sharp changes of direction; react to winning or losing the ball; scan for opponent, others and space; finish quickly once past.', 'Multiple simultaneous 1v1s', NULL, NULL, '30 x 20 m', 30.0, 20.0, 20.0, true, false, true, NULL, 640),
  ('1v1 dribble-through cone gates game', 'one_v_one', 'opposed', 'in_possession', 90, 91, 'Dribbling, Duels and Finishing 2', NULL, 'Beating an opponent with feints, moves and turns, and shielding the ball under pressure.', '40x30 m area with 4 cone gates along each of the two sides (8 gates); 8 players in 1v1 pairs, spare balls around the edge.', 'Each pair plays 1v1 using the whole area; the attacker scores by dribbling through any gate, protecting the ball and attacking space quickly.', 'Goal = dribble through any cone gate; keep score.', NULL, 'Low centre of gravity; shield with body between defender and ball, using an arm; feints, quick direction changes and turns to unbalance.', '8 (four 1v1s)', 8, 8, '40 x 30 m', 40.0, 30.0, 10.0, false, false, true, NULL, 650),
  ('2v2 gate duels, winners move on', 'one_v_one', 'opposed', 'in_possession', 91, 92, 'Dribbling, Duels and Finishing 3', NULL, 'Combining with a partner and dribbling in 2v2 duels under competitive rotation.', '40x30 m area with 3 cone gates along each of the two sides (6 total); players in pairs.', 'Pairs play 2v2 across the whole area, scoring by dribbling through any of the opponents'' gates. After a set time the winners rotate on to face a new pair; on a draw the first pair to score wins.', 'Score through opponents'' gates only. Winners rotate to a new opponent.', 'Progression of Dribbling, Duels and Finishing 2 (1v1 to 2v2).', 'Protect the ball under pressure before attacking space; communicate early to combine; quick changes of direction.', '2v2 pairs', 8, NULL, '40 x 30 m', 40.0, 30.0, 20.0, false, false, true, NULL, 660),
  ('Three-team 8v4, beat your marker first', 'possession', 'overload', 'in_possession', 92, 93, 'Dribbling, Duels and Finishing 4', NULL, 'Committing a defender with a feint or skill before passing, plus fast transitions.', '40x40 m area; three teams of 4. Two teams (8) start in possession against the third team (4).', 'The 8 keep the ball, trying to beat or draw in their marker with dribbling, feints and skills before releasing a pass. Defenders who win it swap roles with the team that lost it.', 'Winning defenders swap with the team that lost the ball.', NULL, 'Beat the marker with a feint or skill before passing; draw the defender then release; create and use passing lines; directional control away from pressure; transition at top speed.', '3 teams of 4 (8v4)', 12, 12, '40 x 40 m', 40.0, 40.0, 20.0, false, false, false, NULL, 670),
  ('5v5 dribble through four pole gates', 'small_sided_game', 'opposed', 'in_possession', 93, 94, 'Dribbling, Duels and Finishing 5', NULL, 'Creating and exploiting space to dribble through goals in a multi-directional game.', '40x40 m square with a pole gate in the middle of each side; two teams of 5.', 'Both teams try to dribble through any of the 4 gates to score; after a goal the scoring team keeps the ball and attacks a different gate.', 'Goal = dribble through a gate; keep the ball after scoring and attack another gate.', NULL, 'Width and depth to stretch the opposition; scan; drive into space changing speed and direction towards the nearest open gate; quick support angles after scoring to switch.', '5v5', 10, 10, '40 x 40 m', 40.0, 40.0, 20.0, true, false, true, NULL, 680),
  ('Beat the mannequin and finish in corners', 'finishing', 'unopposed', 'in_possession', 94, 95, 'Dribbling, Duels and Finishing 6', NULL, 'Back-foot receiving, a decisive 1v1 move and accurate finishing into the corners.', '30x30 m area with a large goal at each end and 3 mannequins in front of each goal; cones mark the corner target areas.', 'Station A: players dribble at a mannequin, beat it with a feint or skill and shoot into either corner. Station B: players move off a cone to receive a pass half-turned on the back foot, beat the mannequin and finish into a corner.', 'Finish wide of the cones (into the corners).', 'Station B is the progression: receive a pass on the half-turn before beating the mannequin.', 'Quick decisive 1v1 moves; receive on the back foot to play forward; finish accurately in the corners.', NULL, NULL, NULL, '30 x 30 m', 30.0, 30.0, 20.0, true, false, true, NULL, 690),
  ('Dribbling wheel with alternate-foot shooting', 'finishing', 'unopposed', 'in_possession', 95, 96, 'Dribbling, Duels and Finishing 7', NULL, 'Close control at speed with both feet, beating mannequins with a feint and shooting with either foot.', 'Two groups start from opposite sides of the half; yellow cone slaloms lead to two mannequins in front of a goal with a goalkeeper.', 'Coach first demonstrates dribbling techniques in a small area. Players dribble through the cones with different techniques, feint one way at each mannequin and accelerate the other, then shoot: left group with the right foot, right group with the left. They then join the other group.', 'Left group shoots right-footed, right group left-footed.', NULL, 'Close control at speed with both feet; change tempo to beat mannequins; balanced body shape when shooting.', '2 groups', NULL, NULL, NULL, NULL, NULL, 20.0, true, true, true, NULL, 700),
  ('Run at speed vs recovering defender, finish', 'one_v_one', 'opposed', 'to_attack', 96, 97, 'Dribbling, Duels and Finishing 8', NULL, 'Running with the ball at speed and finishing under pressure from a chasing defender.', 'Half pitch with a big goal and goalkeeper; cone gate line marks the shooting area at the box; two small wide goals at the other end for the defender''s counter. Attackers and defenders start in lines, attacker slightly ahead.', 'On the coach''s signal the attacker dribbles at speed through the cones into the box and tries to score past the goalkeeper; the defender chases and, if he wins it, counters into one of the small wide goals. Then both move to the opposite side.', 'Defender scores in the small wide goals after winning the ball. Rotate roles regularly.', NULL, 'Push the ball out of the feet to keep speed; use the right part of the foot to accelerate; adapt finishing technique under pressure.', '1v1 + GK', 3, NULL, NULL, NULL, NULL, 20.0, true, true, true, NULL, 710),
  ('Scissor feints past mannequins and finish', 'finishing', 'unopposed', 'in_possession', 97, 98, 'Dribbling, Duels and Finishing 9', NULL, 'Feinting at speed, accelerating away and finishing accurately, with scanning for a coach signal.', '40x30 m area with a goal and goalkeeper; two lines of mannequins (two per side) from left and right starting cones; cones mark target corners.', 'From the left, players dribble at the first mannequin, feint left and burst right (scissor, later double scissor), repeat at the second mannequin, then finish into either corner. The right side mirrors it and shoots left.', 'Finish wide of the cones (corners).', '1) Coach raises a coloured cone to signal which corner to hit. 2) Replace the second mannequin with a live defender for a real 1v1.', 'Feint at speed then accelerate; close control; scan before shooting and react to the signal.', '2 lines + GK', NULL, NULL, '40 x 30 m', 40.0, 30.0, 20.0, true, true, true, NULL, 720),
  ('Pass, receive, 1v1 and finish vs GK', 'one_v_one', 'passive', 'in_possession', 98, 99, 'Dribbling, Duels and Finishing 10', NULL, 'Receiving, dribbling past a passive defender and finishing, with visual awareness of a target corner.', '30x30 m area with a goal and goalkeeper, mannequins on each side; players in lines on left and right.', 'A passes to B, then runs around the mannequin into the area to defend passively. B receives, dribbles forward past the mannequin to take on A in a 1v1 and tries to score. Then the right side goes; players rotate through roles and sides.', 'Defender A applies passive pressure.', '1) Coach raises a red or yellow cone to set the target corner. 2) B receives an aerial pass with the thigh before attacking. 3) B receives an aerial pass with the chest.', NULL, '1v1 + GK', 5, NULL, '30 x 30 m', 30.0, 30.0, 20.0, true, true, true, NULL, 730),
  ('Feint, pass, receive and 1v1 vs defender', 'one_v_one', 'opposed', 'in_possession', 99, 100, 'Dribbling, Duels and Finishing 11', NULL, 'Back-foot receiving, attacking a defender at speed and finishing under pressure.', '40x30 m area with a goal and goalkeeper; a mannequin on each side; midfielder lines on left and right, an attacker and a defender in the middle.', 'The midfielder dribbles forward, beats the mannequin with a feint, then passes to the attacker, who receives on the back foot and dribbles at the defender in a 1v1 to score past the goalkeeper.', 'Rotation: midfielder to attacker to defender.', 'Replace both mannequins with defenders.', 'Well timed and weighted pass; back-foot control to open up; attack at speed to commit the defender; explode away from the feint; finish with composure.', '1v1 + GK + feeders', 4, NULL, '40 x 30 m', 40.0, 30.0, 20.0, true, true, true, NULL, 740),
  ('3v2 attacking overload then 1v1 finish', 'one_v_one', 'overload', 'in_possession', 100, 101, 'Dribbling, Duels and Finishing 12', NULL, 'Using peripheral vision in a 3v2 to get past defenders and finish 1v1 against the goalkeeper.', '30x30 m area with a goal and goalkeeper; 3 attackers each start with a ball from 3 different lines; 2 defenders in front of a line near the goal.', 'All three attackers dribble forward at once trying to get past the 2 defenders and score. After shooting, an attacker can join in to support teammates who have not finished yet. When all three are done, the next three go.', 'Rotate defenders often.', NULL, 'Keep speed and control dribbling to goal; support quickly after your own attack to create overloads.', '3v2 + GK', 6, NULL, '30 x 30 m', 30.0, 30.0, 20.0, true, true, true, NULL, 750),
  ('Three-team 1v1 duels, winners stay', 'one_v_one', 'opposed', 'in_possession', 101, 102, 'Dribbling, Duels and Finishing 13', NULL, 'Attacking with speed and purpose in 1v1s and finishing accurately.', 'Area between two goals with goalkeepers; two teams play three 1v1s side by side; the third team waits outside juggling.', 'Each 1v1 lasts 1 minute; players try to score as many as possible, and after a goal or ball out the opponent restarts attacking the other way. Goals add up for the team; winners stay on, losers swap with the waiting team.', 'Must dribble before shooting. 1-minute games; winners stay.', NULL, 'Attack with speed and purpose; feints and direction changes; close control at speed; scan and react; aim for corners.', '3 teams (three 1v1s)', 9, NULL, NULL, NULL, NULL, 20.0, true, true, true, NULL, 760),
  ('6v6 six small goals game', 'small_sided_game', 'opposed', 'in_possession', 102, 103, 'Dribbling, Duels and Finishing 14', NULL, 'Scanning, quick decisions and creative attacking to choose the best of three goals.', '40x30 m area with 3 small goals on each end line; two teams of 6.', 'Each team attacks 3 goals and defends 3, picking the target by space, pressure and defenders'' positions. Defenders shift and communicate to protect all three. Coach or deepest player restarts quickly to keep tempo.', 'Score in any of the 3 opposing small goals.', NULL, 'Scan before receiving to find the best goal; quick combinations to exploit gaps; react fast to defend or attack all 3 goals.', '6v6', 12, 12, '40 x 30 m', 40.0, 30.0, 20.0, true, false, true, NULL, 770),
  ('Paired striking technique into hands', 'finishing', 'unopposed', NULL, 105, 106, 'Shooting 1', NULL, 'Striking technique with both feet: accuracy, balance and body shape.', '20x20 m area with players in pairs facing each other across lanes.', 'One partner holds the ball, drops and strikes it accurately into the other''s hands, using both feet; partners alternate.', NULL, '1) Move on to half-volley strikes. 2) Increase the distance once technique is good.', 'Strike with the right part of the foot; good balance and body shape; use both feet.', 'Pairs', 2, NULL, '20 x 20 m', 20.0, 20.0, 10.0, false, false, false, NULL, 780),
  ('Volley at the called-colour bib target', 'finishing', 'unopposed', NULL, 106, 107, 'Shooting 2', NULL, 'Accurate volley and half-volley technique aimed at a specific target.', '30x30 m area with a large goal at each end: a yellow bib hung in the centre and 2 orange bibs near the corners; 3 mannequins in front of each goal.', 'The coach calls a colour; players volley or half-volley from their hands trying to hit the bib of that colour.', 'Keep score individually or in teams; most hits wins.', NULL, 'Technique for accuracy over power; adjust body shape to connect cleanly; eyes on target and follow through towards it.', NULL, NULL, NULL, '30 x 30 m', 30.0, 30.0, 10.0, true, false, true, NULL, 790),
  ('Switch pass, dribble, cut back and finish', 'combination', 'unopposed', 'in_possession', 107, 108, 'Shooting 3', NULL, 'Close-control dribbling, timing a support run and finishing a cut-back.', '30x30 m area with a goal and goalkeeper (coloured cones mark the corners), 2 mannequins on each side and a red cone at the bottom; players A and B in lines on opposite sides.', 'A passes across to B, who dribbles past the 2 mannequins and cuts the ball back into the centre. A makes a timed curved run around the red cone to meet the cut-back and finishes into a corner. Players then switch sides.', 'Finish wide of the corner cones.', 'Coach raises a red or yellow cone to set the target corner.', 'Close control near the mannequins; time the support run to meet the cut-back at pace; correct body shape for accuracy.', '2 lines + GK', 3, NULL, '30 x 30 m', 30.0, 30.0, 10.0, true, true, true, NULL, 800),
  ('Four-player passing sequence ending in shot', 'combination', 'unopposed', 'in_possession', 108, 109, 'Shooting 4', NULL, 'Passing, receiving with directional control and finishing with both feet.', '40x30 m area with a goal and goalkeeper; mannequins and cones set a 4-station passing route (A, B, C, D) from one corner round towards goal.', 'Ball travels A to B to C to D, each player using a directional touch to set the ball into space before passing. D takes a forward touch on the back foot and shoots past the goalkeeper. Each player follows his pass to the next cone.', 'Follow your pass; repeat from the other side.', 'Run the sequence from the left side too, to work both feet.', 'Back-foot directional control; accurate, weighted, timed passes; set body shape early for the shot and follow through.', '4+ and GK', 5, NULL, '40 x 30 m', 40.0, 30.0, 10.0, true, true, true, NULL, 810),
  ('Arched run onto own pass and shoot', 'finishing', 'unopposed', 'in_possession', 109, 110, 'Shooting 5', NULL, 'Making a deep arched run to widen the shooting angle and striking cleanly.', '40x30 m area with a goal and goalkeeper at each end; poles in the centre, a yellow and a red mannequin on each side; players in lines with balls.', 'Each player passes between the poles towards the centre, runs in an arc around the yellow mannequin, meets his own pass and shoots with the right foot from just outside the area, then switches side and collects a new ball.', 'After a set time switch sides: run round the red mannequin and shoot with the left foot.', NULL, 'Deep arched run to open the angle; time the run and contact for accurate, powerful shots.', NULL, NULL, NULL, '40 x 30 m', 40.0, 30.0, 20.0, true, true, true, NULL, 820),
  ('Left/right call 1v1 race and finish', 'one_v_one', 'opposed', 'in_possession', 110, 111, 'Shooting 6', NULL, 'Reacting fast to a signal, a positive first touch and finishing under a recovering defender.', '30x20 m area with a goal and goalkeeper at each end; red, blue and yellow cones form gates in the middle; two teams face each other in two lines with balls diagonally opposite.', 'Players pass back and forth to the opponent opposite until the coach calls Right or Left. The players with a ball then dribble through the far gate and shoot with that foot, while the other runs round a middle cone and through a gate to defend 1v1. Next players go.', 'Shoot with the called foot; team with most goals wins.', NULL, 'Stay light and react to the signal; positive first touch to set the finish; right foot to finish under pressure; defenders recover fast and close the angle.', '2 teams in 2 lines + 2 GK', 6, NULL, '30 x 20 m', 30.0, 20.0, 15.0, true, true, true, NULL, 830),
  ('3v1 breakaway with two recovering defenders', 'transition', 'overload', 'to_attack', 111, 112, 'Shooting 7', NULL, 'Attacking quickly to exploit a temporary overload before defenders recover.', '25x20 m area with a large goal and goalkeeper at one end and 2 small goals at the other; 3 blue attackers face 3 white defenders.', 'On go the middle pair exchange passes, then the blue plays a one-two with the white opposite to start a 3v1 breakaway; the other 2 whites run round the blue cones before joining, so blues must score before it is 3v3.', 'If the whites win the ball they counter into either small goal.', NULL, 'Attack at speed; wide runs and angled support to stretch the defender; shoot early; defenders recover flat out to narrow space.', '3v1 (+2 recovering) + GK', 7, NULL, '25 x 20 m', 25.0, 20.0, 15.0, true, true, true, NULL, 840),
  ('Three-team rotating 2v2 to goal', 'one_v_one', 'opposed', 'in_possession', 112, 113, 'Shooting 8', NULL, 'Quick combinations and sharp finishing in competitive 2v2 duels.', '30x30 m area with a goal and goalkeeper; red cone starts and blue pole gates; three teams of 4 in pairs.', 'A defender dribbles from the red cone and passes to an attacker, then runs through the pole gate to defend 2v2 with his partner. The attacker receives and goes forward with his partner to score. Whatever happens, the next 2 pairs go.', 'Keep score; team with most goals wins.', NULL, 'Attack with speed and purpose; quick combinations for shots; sharp finishing; stay composed under pressure.', '3 teams of 4 (2v2) + GK', 13, NULL, '30 x 30 m', 30.0, 30.0, 20.0, true, true, true, NULL, 850),
  ('Three-zone 4v2 build-up to 2+2v1 finish', 'phase_of_play', 'overload', 'in_possession', 113, 114, 'Shooting 9', NULL, 'Breaking lines through successive zones with overloads and finishing decisively.', '35x25 m area split into a build-up zone (2 small goals behind it), a middle zone and a scoring zone in front of a large goal with goalkeeper; 2 jokers stand at the sides of the scoring zone.', 'On go, 4 blues play 4v2 in the build-up zone and pass through the press to a player receiving in the middle zone, with the passer moving up to make 2v1 against 1 defender. The ball is played into the scoring zone where 2 attackers plus 2 jokers face 1 defender and finish.', 'If defenders win the ball they score in either small goal.', 'Variation: if a player dribbles into the middle zone instead of receiving a pass, 3 blues go into the scoring zone for a 3v1 without the jokers.', 'Finish decisively once the advantage is created.', '4v2, 2v1, 2+2v1 + GK', NULL, NULL, '35 x 25 m', 35.0, 25.0, 20.0, true, true, true, NULL, 860),
  ('5v5 Aussie rules volley game', 'small_sided_game', 'opposed', 'in_possession', 114, 115, 'Shooting 10', NULL, 'Aerial passing, receiving in the air and finishing with volleys and headers.', '30x30 m area with a large goal at each end; two teams of 5.', 'The ball is moved by volleying, half-volleying or catching it in the hands to keep possession; after 5 passes a team may score, but only with a header or volley.', '5 consecutive passes before scoring; goals only by header or volley; if the ball touches the ground possession goes to the other team.', NULL, 'Communicate early to receive in the air; adjust body shape to control aerial passes; time runs to attack the ball for a volley or header.', '5v5', 10, 10, '30 x 30 m', 30.0, 30.0, 20.0, true, false, true, NULL, 870),
  ('Number call 4v4 quick shooting game', 'small_sided_game', 'opposed', 'to_attack', 115, 116, 'Shooting 11', NULL, 'Reacting instantly and shooting early before the opposition is organised.', '30x30 m area with two large goals and goalkeepers; two teams of 4 inside, the third team of 4 numbered 1-4 around the sides, each with a ball.', 'The coach calls a number; that outside player passes in to one team, which tries to score as fast as possible while the other team scrambles to organise.', NULL, NULL, 'React to the call and switch on; play at high tempo against a disorganised defence; be decisive and shoot early.', '3 teams of 4 (4v4 + 4 servers) + 2 GK', 14, 14, '30 x 30 m', 30.0, 30.0, 20.0, true, true, true, NULL, 880),
  ('2v2+4 quick shooting with end supporters', 'small_sided_game', 'overload', 'in_possession', 116, 117, 'Shooting 12', NULL, 'High-tempo shooting, using support players to combine and open space.', 'Penalty-area sized pitch between two large goals with goalkeepers; 4 pairs: 2 pairs play 2v2 inside, the other 2 pairs stand as support players beside each goal on the end lines.', 'A goalkeeper starts play; the pairs inside try to create as many shots as possible, combining with the end-line supporters. Goalkeeper restarts after a goal or ball out.', 'Rotate roles after a set time or number of goals.', NULL, 'High speed of play and lots of shots; use supporters to create chances; be direct; finish accurately under pressure.', '2v2 (+4) + 2 GK', 10, 10, NULL, NULL, NULL, 20.0, true, true, true, NULL, 890),
  ('Three-team 3v3 winner stays, 5-pass limit', 'small_sided_game', 'opposed', 'in_possession', 117, 117, 'Shooting 13', NULL, 'Quick decisions and confident early shooting, including with the weaker foot.', 'Penalty-area sized pitch between two large goals with goalkeepers; three teams of 3, one resting at the side.', 'Two teams play 3v3; first goal wins, and the losing team rotates off for the waiting team.', 'Maximum 5 passes before shooting; a sixth pass gives possession to the other team.', NULL, 'Quick decisions under pressure; movement and sharp passing to create space; shoot quickly with either foot.', '3 teams of 3 + 2 GK', 11, 11, NULL, NULL, NULL, 20.0, true, true, true, NULL, 900),
  ('4v4+2 end-to-end build-up with roles', 'positional_game', 'overload', 'in_possession', 120, 120, 'Tactical Positional Play 1', NULL, 'Spacing, support angles and positional roles when building play from one end zone to the other.', 'Area across half a pitch with an end zone at each end; two teams of 4 (2 full backs and 2 central midfielders each) plus 2 neutral players, one in each end zone.', 'One neutral starts as a centre back and builds up; the team on the ball works it through the middle to the other neutral acting as forward. When the forward receives he becomes the centre back and play goes back the other way.', 'Neutrals stay in the end zones and play with the team in possession.', NULL, 'Coach exact positions and roles so players know where to be in possession; spacing, angles and movement in real game zones.', '4v4+2', 10, 10, NULL, NULL, NULL, 20.0, false, false, true, NULL, 910),
  ('Play wide and dribble forward 7v7', 'small_sided_game', 'opposed', 'in_possession', 121, 121, 'Tactical Positional Play: Practice 2', NULL, 'Recognise when to play wide to the full backs and when and where to dribble forward into space.', 'Half a 7-a-side pitch; one big goal with a keeper at one end, three small goals along the halfway line. Both teams set up 3-2-1.', 'Keeper starts play; team attacking the big goal looks to get the ball wide to a full back, who drives forward with the ball and combines with midfielders. Other team attacks the three small goals.', NULL, NULL, 'Full backs get open early and attack the flank; dribble when space is ahead; coach quizzes players at the end on key dribbling moments.', '7v7 incl. 1 GK', 14, 14, 'Half of 7-a-side pitch', NULL, NULL, 30.0, true, true, true, 'U7-U12', 920),
  ('Defensive shape and pressing triggers 4v4+2', 'defending', 'overload', 'out_of_possession', 122, 122, 'Tactical Positional Play: Practice 3', NULL, 'Defend as a compact unit: pressing angles, shifting together and blocking passing lanes to force predictable play.', '7-a-side pitch with a goal and keeper at each end; 4v4 in a 3-2-1 style shape plus 2 neutral jokers acting as full backs in wide side zones.', 'Jokers play with the team in possession to stretch play. The defending forward angles his press to send the centre back one way, the midfielders stay tight to intercept and jump on the trigger, and the unit shifts across to force play backwards or wide.', 'Jokers stay in their wide zones.', 'Rotate roles regularly so everyone defends from each position.', 'Forward''s curved press closes one side; CMs close enough to support and intercept; quick shifts as a unit.', '4v4+2 jokers + 2 GKs', 12, 12, '7-a-side pitch', NULL, NULL, 30.0, true, true, true, 'U7-U12', 930),
  ('Academy playing philosophy 7v7 (3-2-1)', 'small_sided_game', 'opposed', 'in_possession', 125, 126, 'Tactical 7v7 Positional SSG: 1a', NULL, 'Teach correct positioning and role duties in the 3-2-1 shape, in and out of possession.', 'Full 7-a-side pitch, goal and keeper each end, both teams in 3-2-1; coach on the side with balls to keep play flowing.', 'Free 7v7 game. Coach freezes play whenever a positional mistake happens and asks the player what he could do (e.g. overlap to give the defence a problem). Players gather halfway through to review key points.', 'Players swap positions every 10 minutes.', NULL, 'Keep possession and take the initiative; open up wide and long; GK plays on the ground, CB always a safe option, full backs give maximum width, CMs move as if tied by a rope, forward plays high and presses the restart.', '7v7 incl. GKs', 14, 14, '7-a-side pitch', NULL, NULL, NULL, true, true, true, 'U7-U12', 940),
  ('Build up from the back 7v7', 'small_sided_game', 'opposed', 'in_possession', 129, 129, 'Tactical 7v7 Positional SSG: 2', NULL, 'Play out from the keeper with short ground passes, width and angled support.', '7-a-side pitch, goal and keeper each end, both teams in 3-2-1.', 'Keeper starts every attack on the ground to the CB, who receives half-turned while the full backs spread as wide as possible; CMs move off their markers to give angled options and the forward offers depth or drops to link.', 'Teams are encouraged to build from the back.', NULL, 'At least 2 safe passing options at all times; CB scans before receiving; stay composed when recycling.', '7v7 incl. GKs', 14, 14, '7-a-side pitch', NULL, NULL, NULL, true, true, true, 'U7-U12', 950),
  ('Advanced attacking full backs 7v7', 'small_sided_game', 'opposed', 'in_possession', 130, 131, 'Tactical 7v7 Positional SSG: 3 (3a/3b)', NULL, 'Use full backs to push on, overlap and create wide overloads, then finish attacks.', '7-a-side pitch, goal and keeper each end, both teams in 3-2-1.', 'Part 1: full back overlaps to support the forward in wide areas while one CM tucks in for balance and the far full back stays wide. Part 2: from the wide overload both full backs push high into the final third to cross, cut back or finish, with CMs holding inside to cover.', NULL, '3a supporting overlaps to build the overload; 3b full backs advance further and join the finish in the final third.', 'Timing of the overlap; one CM always inside for balance; coach freezes play and asks how to support the forward.', '7v7 incl. GKs', 14, 14, '7-a-side pitch', NULL, NULL, NULL, true, true, true, 'U7-U12', 960),
  ('Third man and overlapping runs 7v7', 'small_sided_game', 'opposed', 'in_possession', 132, 133, 'Tactical 7v7 Positional SSG: 4 (4a/4b)', NULL, 'Create overloads with third-man combinations and a central midfielder''s overlapping run, while keeping balance.', '7-a-side pitch, goal and keeper each end, both teams in 3-2-1.', 'Part 1: a CM overlaps or makes a third-man run to support the forward wide, the other CM tucks in. Part 2: in the final third, when a CM breaks forward the full back on that side steps inside to cover, keeping security while the attack is finished.', NULL, '4a CM overlap / third-man run; 4b retaining balance while finishing (full back covers inside when a CM runs beyond).', 'Recognise when to release to the third man; always keep one midfielder tucked in; time forward runs.', '7v7 incl. GKs', 14, 14, '7-a-side pitch', NULL, NULL, NULL, true, true, true, 'U7-U12', 970),
  ('Build-up play options 7v7', 'small_sided_game', 'opposed', 'in_possession', 134, 137, 'Tactical 7v7 Positional SSG: 5 (5a-5d)', NULL, 'Read the full backs'' and midfielders'' positions to pick the right build-up solution: combine, switch, play direct or recycle.', '7-a-side pitch, goal and keeper each end, both teams in 3-2-1; full backs set deep or advanced to create different options.', 'Keeper starts build-up and the team chooses among options depending on positions: CM wall pass or switch based on the full back (5a), direct diagonal from full back to forward with CM exploiting space (5b), switch through the CMs when full backs are high and wide (5c), or reset back through CB and keeper and rotate when forward is blocked (5d).', NULL, 'Option 1 CM pass-or-switch; Option 2 direct pass to forward + CM run; Option 3 switch through central midfielders; Option 4 reset and rotate under pressure. Example Session 1 #6 reuses option 2 with players told to run with the ball into space once they receive in behind.', 'Scan before receiving, half-turned body shape using the back foot; CB is the escape option; patience in possession.', '7v7 incl. GKs', 14, 14, '7-a-side pitch', NULL, NULL, NULL, true, true, true, 'U7-U12', 980),
  ('Attacking combinations 7v7', 'small_sided_game', 'opposed', 'in_possession', 138, 141, 'Tactical 7v7 Positional SSG: 6 (6a-6d)', NULL, 'Rehearse combinations between CMs, forward and full backs to draw pressure inside and exploit the space it opens.', '7-a-side pitch, goal and keeper each end, both teams in 3-2-1.', 'CMs combine centrally with the forward to pull defenders in, then release the full back wide (6a); forward drifts wide to drag the CB and open the centre for a CM (6b); forward runs to the weak side then attacks the box (6c); full back and forward rotate so the forward receives wide when the central pass is blocked (6d).', NULL, 'Options 1-4 as listed; Example Session 4 #6 reuses options 1 and 3 with the condition to shoot or attack the box.', 'CM dictates tempo; forward''s diagonal runs drag defenders; scan and decide quickly whether to go wide or combine inside.', '7v7 incl. GKs', 14, 14, '7-a-side pitch', NULL, NULL, NULL, true, true, true, 'U7-U12', 990),
  ('Defensive roles and positioning 7v7', 'defending', 'opposed', 'out_of_possession', 143, 145, 'Tactical 7v7 Positional SSG: 7 (7a-7c)', NULL, 'Defend as a team in the 3-2-1: block lanes, stay compact, shift together and press on triggers to win the ball back.', '7-a-side pitch, goal and keeper each end, both teams in 3-2-1.', 'Team works on a high-press mid-block: forward presses the keeper to one side, one CM presses while the other covers, CB marks the forward and organises the back three, full backs tuck in when the ball is central (7a). When the keeper plays wide, the nearest full back engages and the unit slides across (7b). Forward blocks inside lanes to trigger a trap that forces a pass down the channel (7c).', NULL, 'Option 1 team shape / high press mid-block; Option 2 response to keeper''s pass wide; Option 3 forward''s pressing trigger forcing play wide.', 'Never both CMs chase the ball; keeper stays high to sweep; back three level; communication between defenders and midfielders.', '7v7 incl. GKs', 14, 14, '7-a-side pitch', NULL, NULL, NULL, true, true, true, 'U7-U12', 1000)
) AS v(t, cat, opp, m, pf, pt, ref, coach, obj, setup, proc, rules, prog, cp, players, mn, mx, area, len, wid, dur, goals, gk, dir, age, so)
JOIN exercise_categories c ON c.code = v.cat
CROSS JOIN (SELECT id, source_id FROM coaching_books WHERE slug = 'catalan-academy-coaching-u7-12-the-world-s-best-youth-training-program-110-pract') b;
INSERT INTO schema_migrations (filename) VALUES ('2404-exercises-book-catalan-academy-coaching-u7-12-the-world-s-best-youth-traini.sql') ON CONFLICT DO NOTHING;
COMMIT;
